-- The full map of Lebanon for picking where someone is: 26 districts
-- (qadas) and 1,610 cadastral areas under the 8 governorates, in Arabic
-- and English with coordinates. Source: Open Admin Data, "Lebanon
-- Administrative Divisions" (https://github.com/open-admin-data/lebanon-administrative-divisions),
-- CC-BY-4.0 -- credited on /terms. A few everyday names are added to the
-- areas they belong to (Hamra -> Ras Beyrouth, Dora -> Bourj Hammoud).
--
-- Profiles keep location_id = governorate (matching and filters work as
-- before); the district and area are stored on top (attributes.districtId
-- / areaId). The older hand-entered district/area rows have no code and
-- are left alone for anything that still points at them.

alter table public.locations add column code text unique;
alter table public.locations add column lat double precision;
alter table public.locations add column lon double precision;
-- Normalized names (Arabic and English, plus everyday aliases) that the
-- area search matches against -- see normalizeAreaText in src/lib/areas.ts.
alter table public.locations add column search_text text;
create index locations_code_level_idx on public.locations(level) where code is not null;

update public.locations set code = 'LB7', lat = 34.552, lon = 36.201, search_text = 'akkar | عكار | akkar' where level = 'governorate' and name_en = 'Akkar';
update public.locations set code = 'LB8', lat = 34.168, lon = 36.297, search_text = 'baalbek el hermel | بعلبك الهرمل | baalbek hermel' where level = 'governorate' and name_en = 'Baalbek-Hermel';
update public.locations set code = 'LB1', lat = 33.889, lon = 35.502, search_text = 'beirut | بيروت | beirut' where level = 'governorate' and name_en = 'Beirut';
update public.locations set code = 'LB2', lat = 33.64, lon = 35.81, search_text = 'bekaa | البقاع | beqaa' where level = 'governorate' and name_en = 'Beqaa';
update public.locations set code = 'LB4', lat = 33.283, lon = 35.497, search_text = 'el nabatieh | النبطيه | nabatieh' where level = 'governorate' and name_en = 'Nabatieh';
update public.locations set code = 'LB3', lat = 33.851, lon = 35.648, search_text = 'mount lebanon | جبل لبنان | mount lebanon' where level = 'governorate' and name_en = 'Mount Lebanon';
update public.locations set code = 'LB5', lat = 34.32, lon = 35.937, search_text = 'north | الشمال | north lebanon' where level = 'governorate' and name_en = 'North Lebanon';
update public.locations set code = 'LB6', lat = 33.342, lon = 35.304, search_text = 'south | الجنوب | south lebanon' where level = 'governorate' and name_en = 'South Lebanon';


